def find_sums():
    squares = [x**2 for x in range(1, 26, 2)]
    roots = {x**2: x for x in range(1, 26, 2)}

    valid = []
    for s1 in squares:
        for s2 in squares:
            for s3 in squares:
                for s4 in squares:
                    if s1 + s2 + s3 + s4 == 668:
                        ans = tuple(sorted([roots[s1], roots[s2], roots[s3], roots[s4]], reverse=True))
                        if ans not in valid:
                            valid.append(ans)
    print("Valid sums (absolute values) for the 4 sequences:")
    for v in valid:
