import math
import itertools

def find_sum_squares():
    target = 668
    results = set()
    limit = int(math.sqrt(target)) + 1

    for a in range(1, limit, 2):
        for b in range(1, limit, 2):
            for c in range(1, limit, 2):
                for d in range(1, limit, 2):
                    if a*a + b*b + c*c + d*d == target:
                        res = tuple(sorted([a, b, c, d], reverse=True))
                        results.add(res)

    for r in sorted(results):
        print(f"{r[0]:>2}^2 + {r[1]:>2}^2 + {r[2]:>2}^2 + {r[3]:>2}^2 = {r[0]**2} + {r[1]**2} + {r[2]**2} + {r[3]**2} = 668")

